static const float TEST_EPSILON = 1.0e-2f;

void test_evd() {
	TRACE();

	ComplexF _Cov[] = {

			ComplexF(1.0908232779173798e+02, 0.0000000000000000e+00), ComplexF(-1.1272765527515222e+01, 1.8151014366810440e+01), ComplexF(-3.9583418495542784e+00, -3.9252635233884225e-01), ComplexF(2.2530746781922497e+00, -7.7635871007055250e+00),
			ComplexF(-1.1272765527515222e+01, -1.8151014366810440e+01), ComplexF(1.0920596497769982e+02, 0.0000000000000000e+00), ComplexF(-1.0042573575581210e+01, 1.7272282237243456e+01), ComplexF(-1.7618055840305513e+00, -4.8384177302635578e-01),
			ComplexF(-3.9583418495542784e+00, 3.9252635233884225e-01), ComplexF(-1.0042573575581210e+01, -1.7272282237243456e+01), ComplexF(1.0826672508973246e+02, 0.0000000000000000e+00), ComplexF(-7.1034020661801698e+00, 1.3940649959196811e+01),
			ComplexF(2.2530746781922497e+00, 7.7635871007055250e+00), ComplexF(-1.7618055840305513e+00, 4.8384177302635578e-01), ComplexF(-7.1034020661801698e+00, -1.3940649959196811e+01), ComplexF(1.1090750047701481e+02, 0.0000000000000000e+00),

	};
	MatrixCmpl Cov(4, 4, _Cov);

	struct evd_tol_s tol;
	MatrixCmpl V(4, 4, MATRIX_UNINIT_DATA);
	MatrixF d(1, 4, MATRIX_UNINIT_DATA);

	tol.maxeig = 1.0e-4f;
	tol.sumeig = 0.99f;

	evd(Cov, tol, d.cols(), V, d);

	//std::cout <<  generateInitializer< ComplexF >(V, "V");
	//std::cout <<  generateInitializer< MatrixF >(d, "d");

	ComplexF _Vref[] = {
			ComplexF(4.7970102688654415e-01, 2.0026483923261102e-16), ComplexF(4.9105426027207311e-01, -4.7665929575912456e-16), ComplexF(5.6690092121793823e-01, -1.4564832739489913e-15), ComplexF(4.5538441124350759e-01, 5.2419584545230850e-17),
			ComplexF(-2.0269506532202816e-01, -5.6339495878924162e-01), ComplexF(-3.8665768217198554e-01, -7.3843668082800976e-02), ComplexF(2.3260627608173173e-01, 9.5543550948801778e-02), ComplexF(3.4089491833121888e-01, 5.5416602683111993e-01),
			ComplexF(-4.1739006366650644e-01, 3.1845542467018473e-01), ComplexF(3.2857744221309892e-01, -2.5906850524255259e-01), ComplexF(2.6766683800495111e-01, -4.3081869441999138e-01), ComplexF(-2.4785139413180357e-01, 4.8022061235550345e-01),
			ComplexF(2.7429000530431341e-01, 2.4601712531798353e-01), ComplexF(-6.3585707087330845e-01, 1.5657209984737278e-01), ComplexF(5.3127468841661174e-01, -2.7547416855352003e-01), ComplexF(-2.6464869145047171e-01, -8.5056612723208580e-02),
	};

	MatrixCmpl Vref(4, 4, _Vref);
	TEST_ASSERT_TRUE(test_cmp(V, Vref, TEST_EPSILON));

	float _dref[] = { 144.1381, 117.3904, 97.5696, 78.3643, };
	MatrixF dref(1, 4, _dref);
	TEST_ASSERT_TRUE(test_cmp(d, dref, TEST_EPSILON));

}

